def experiment(inputs):
    parameters = inputs.get('parameters', {'scale': 1.0})
    seeds = inputs.get('seeds', [13, 71, 43])
    measurements = {'metric': []}
    import random
    for seed in seeds:
        rng = random.Random(seed)
        val = rng.gauss(0, parameters.get('scale', 1.0))
        measurements['metric'].append(val)
    return {'measurements': measurements}
